    'chapter' => 'theory',
    'sourceId' => 'depolarization-repolarization-ecg',
    'stem' => '按本站《除极、复极与体表波形》课程，以下哪项描述正确？',
    'options' =>
    array (
      0 => '定位前先排除左束支阻滞、预激、心室起搏、左室肥厚与心包炎等会改变 ST-T 的图形；再结合症状、肌钙蛋白与动态演变判断。',
      1 => '心肌梗死定位的核心是：ST 段抬高的导联大致面向梗死区域，而相反方向的导联出现镜像性 ST 压低。相邻导联至少两个满足阈值才有定位意义，单导联抬高更容易受早期复极、导联错位或正常变异影响。',
      2 => '除极从心内膜向心外膜推进，若朝向正电极，记录为正向波；复极从心外膜向心内膜推进，方向相反，因此 T 波在多数导联与 QRS 主波同向。',
      3 => '后壁位于心脏后方，标准 12 导联没有直接面向它的电极。后壁损伤向量背离 V1–V3，因此在这三个导联上表现为 ST 压低、R 波增高、T 波直立，这三联征比单独 ST 压低更特异。',
    ),
    'answerIndex' => 2,
    'explanation' => '《除极、复极与体表波形》教学要点：除极从心内膜向心外膜推进，若朝向正电极，记录为正向波；复极从心外膜向心内膜推进，方向相反，因此 T 波在多数导联与 QRS 主波同向。',
    'difficulty' => 1,
  ),
