  197 =>
  array (
    'id' => 'sec-hypertrophy-023',
    'chapter' => 'hypertrophy',
    'sourceId' => 'biatrial-enlargement',
    'stem' => '按本站《双心房增大》课程，以下哪项描述正确？',
    'options' =>
    array (
      0 => '房室结位于 Koch 三角内，靠近三尖瓣隔瓣、冠状窦口与 Todaro 腱。房室结传导速度慢，形成 PR 段的大部分，使心房收缩能够先于心室。',
      1 => '窦房结并非一个“点”，而是有起搏细胞与过渡细胞的复合结构；其血供多来自右冠状动脉或左回旋支，缺血可导致窦性心动过缓或停搏。',
      2 => '窦房结位于上腔静脉与右心房交界处的界沟附近，是正常心脏的最高起搏点。冲动沿心房肌和结间束向房室结传播，同时激动右房与左房，形成体表 P 波。',
      3 => '右房与左房除极向量叠加，使 P 波振幅和时间同时增加；V1 的双相 P 波可分别反映右房与左房。',
    ),
    'answerIndex' => 3,
    'explanation' => '《双心房增大》教学要点：右房与左房除极向量叠加，使 P 波振幅和时间同时增加；V1 的双相 P 波可分别反映右房与左房。',
    'difficulty' => 2,
  ),
