    'sourceId' => 'lvh-voltage',
    'stem' => '按本站《左心室肥厚电压标准》课程，以下哪项是一句话描述？',
    'options' =>
    array (
      0 => '窦房结主导：P 波在 I、II、aVF 直立，每个 P 后跟随 QRS，频率 60–100 次/分。',
      1 => '左室肥厚使左室除极向量增大，胸导联 R 波增高、S 波加深；常用 Sokolow-Lyon、Cornell 等电压标准。',
