    ),
    'answerIndex' => 1,
    'explanation' => '《左心室肥厚电压标准》的一句话描述：左室肥厚使左室除极向量增大，胸导联 R 波增高、S 波加深；常用 Sokolow-Lyon、Cornell 等电压标准。',
    'difficulty' => 2,
  ),
  200 =>
  array (
    'id' => 'sec-hypertrophy-026',
    'chapter' => 'hypertrophy',
    'sourceId' => 'lvh-voltage',
    'stem' => '按本站《左心室肥厚电压标准》课程，以下哪项是最具特异性的线索？',
    'options' =>
    array (
      0 => '最具特异性的是“窦性 P 波电轴（I、II、aVF 直立，aVR 倒置）+ 每个 P 后固定 PR 的 QRS”；P 波形态在同一导联保持一致。',
      1 => 'Sokolow-Lyon：SV1 + RV5/V6 ≥3.5 mV；Cornell：RaVL + SV3 >2.8 mV（男）/2.0 mV（女）。',
