    ),
    'answerIndex' => 1,
    'explanation' => '《左心室肥厚电压标准》的最具特异性的线索：Sokolow-Lyon：SV1 + RV5/V6 ≥3.5 mV；Cornell：RaVL + SV3 >2.8 mV（男）/2.0 mV（女）。',
    'difficulty' => 2,
  ),
