      0 => '房室结位于 Koch 三角内，靠近三尖瓣隔瓣、冠状窦口与 Todaro 腱。房室结传导速度慢，形成 PR 段的大部分，使心房收缩能够先于心室。',
      1 => '肺过度充气增加胸壁阻抗、心脏位置下移，导致低电压与导联轴改变；肺动脉高压引起右室肥厚。',
      2 => '窦房结位于上腔静脉与右心房交界处的界沟附近，是正常心脏的最高起搏点。冲动沿心房肌和结间束向房室结传播，同时激动右房与左房，形成体表 P 波。',
      3 => '窦房结并非一个“点”，而是有起搏细胞与过渡细胞的复合结构；其血供多来自右冠状动脉或左回旋支，缺血可导致窦性心动过缓或停搏。',
    ),
    'answerIndex' => 1,
    'explanation' => '《COPD 与右心负荷心电图》教学要点：肺过度充气增加胸壁阻抗、心脏位置下移，导致低电压与导联轴改变；肺动脉高压引起右室肥厚。',
    'difficulty' => 2,
  ),
