    'explanation' => '《未下传的房性早搏》教学要点：房性早搏起源于窦房结以外的心房异位起搏点，提前发放冲动。如果这个冲动到达房室结时，房室结仍处于上一次激动的有效不应期，冲动就不能下传到心室，心电图上只看到提前的 P 波而没有 QRS。',
