      0 => '正常窦性心律指冲动由窦房结发出，按固定顺序经心房、房室结、希氏束-浦肯野系统下传，形成形态一致的 P 波与窄 QRS 波群。',
      1 => '二度 I 型房室传导阻滞是房室结传导逐渐延迟，PR 间期逐搏延长，直至一个心房冲动不能下传、QRS 脱漏，随后 PR 缩短并开始新的周期。脱漏使心室率低于心房率，典型者呈 4:3 或 3:2 传导，QRS 多窄，多属房室结内阻滞，常与迷走张力增高或药物有关。',
