      3 => '窦性心动过速是窦房结发放冲动频率超过 100 次/分的状态，P 波形态仍为窦性且与 QRS 一一对应。',
    ),
    'answerIndex' => 1,
    'explanation' => '《二度 I 型房室传导阻滞》的定义：二度 I 型房室传导阻滞是房室结传导逐渐延迟，PR 间期逐搏延长，直至一个心房冲动不能下传、QRS 脱漏，随后 PR 缩短并开始新的周期。脱漏使心室率低于心房率，典型者呈 4:3 或 3:2 传导，QRS 多窄，多属房室结内阻滞，常与迷走张力增高或药物有关。',
    'difficulty' => 2,
