    'sourceId' => 'av-block-2b',
    'stem' => '按本站《二度 II 型房室传导阻滞》课程，以下哪项是定义？',
    'options' =>
    array (
      0 => '窦性心动过速是窦房结发放冲动频率超过 100 次/分的状态，P 波形态仍为窦性且与 QRS 一一对应。',
      1 => '二度 II 型房室传导阻滞是在固定 PR 间期下突然发生 QRS 脱漏，脱漏前没有 PR 进行性延长。阻滞部位多在希氏束或双侧束支水平，常伴 QRS 增宽，进展为完全性房室阻滞的风险较高。它与二度 I 型的本质区别在于阻滞位于房室结以下，而非房室结内的渐进性疲劳。',
      2 => '窦性心动过缓是窦房结发放冲动的频率低于 60 次/分，P 波形态与房室传导顺序仍属正常；生理性多见于运动员与睡眠状态，病理性可见于药物抑制、甲状腺功能减退、缺血或病态窦房结综合征。',
      3 => '正常窦性心律指冲动由窦房结发出，按固定顺序经心房、房室结、希氏束-浦肯野系统下传，形成形态一致的 P 波与窄 QRS 波群。',
    ),
    'answerIndex' => 1,
    'explanation' => '《二度 II 型房室传导阻滞》的定义：二度 II 型房室传导阻滞是在固定 PR 间期下突然发生 QRS 脱漏，脱漏前没有 PR 进行性延长。阻滞部位多在希氏束或双侧束支水平，常伴 QRS 增宽，进展为完全性房室阻滞的风险较高。它与二度 I 型的本质区别在于阻滞位于房室结以下，而非房室结内的渐进性疲劳。',
    'difficulty' => 2,
  ),
