      1 => '窦性心动过缓是窦房结发放冲动的频率低于 60 次/分，P 波形态与房室传导顺序仍属正常；生理性多见于运动员与睡眠状态，病理性可见于药物抑制、甲状腺功能减退、缺血或病态窦房结综合征。',
