      0 => '急性心包炎是心包脏层与壁层的急性炎症，常由病毒、结核、自身免疫病、尿毒症或肿瘤引起。炎症累及心外膜下心肌，产生弥漫性损伤电流，心电图上表现为多导联凹面 ST 抬高与 PR 段压低，临床常伴胸痛与心包摩擦音。',
