    'options' =>
    array (
      0 => '最具特异性的是“窦性 P 波 + 1:1 房室传导 + 心率 >100 次/分”；P 波形态正常、起止相对渐进，有助于与折返性心动过速鉴别。',
      1 => '最具特异性的是“窦性 P 波 + 每个 P 后均有 QRS + 心率 <60 次/分”；与二度/三度阻滞的鉴别在于没有 P 波脱漏或房室分离。',
      2 => 'V1–V3 ST 压低伴 R 波增高、T 波直立构成后壁镜像三联征；V7–V9 相邻导联 ST 抬高 ≥1 mm 可证实后壁梗死。孤立 V1–V3 ST 压低且无高 R、直立 T 或下壁抬高时，更可能为前壁心内膜下缺血。',
