    'answerIndex' => 2,
    'explanation' => '《急性后壁 ST 段抬高型心肌梗死》的最具特异性的线索：V1–V3 ST 压低伴 R 波增高、T 波直立构成后壁镜像三联征；V7–V9 相邻导联 ST 抬高 ≥1 mm 可证实后壁梗死。孤立 V1–V3 ST 压低且无高 R、直立 T 或下壁抬高时，更可能为前壁心内膜下缺血。',
    'difficulty' => 3,
