      0 => '正常窦性心律指冲动由窦房结发出，按固定顺序经心房、房室结、希氏束-浦肯野系统下传，形成形态一致的 P 波与窄 QRS 波群。',
      1 => '急性后壁心肌梗死通常由右冠状动脉或回旋支闭塞引起，后壁损伤向量背离 V1–V3，因此在常规 12 导联上表现为 V1–V3 ST 压低、R 波增高与 T 波直立，而不是直接 ST 抬高。加做 V7–V9 后可在后壁导联看到 ST 抬高。后壁梗死很少孤立发生，常与下壁或侧壁梗死合并，容易被误判为前壁缺血。',
