      3 => '窦性心动过速是窦房结发放冲动频率超过 100 次/分的状态，P 波形态仍为窦性且与 QRS 一一对应。',
    ),
    'answerIndex' => 1,
    'explanation' => '《急性后壁 ST 段抬高型心肌梗死》的定义：急性后壁心肌梗死通常由右冠状动脉或回旋支闭塞引起，后壁损伤向量背离 V1–V3，因此在常规 12 导联上表现为 V1–V3 ST 压低、R 波增高与 T 波直立，而不是直接 ST 抬高。加做 V7–V9 后可在后壁导联看到 ST 抬高。后壁梗死很少孤立发生，常与下壁或侧壁梗死合并，容易被误判为前壁缺血。',
    'difficulty' => 3,
  ),
