    'chapter' => 'pediatric',
    'sourceId' => 'kawasaki-ecg',
    'stem' => '按本站《川崎病心电图》课程，以下哪项描述正确？',
    'options' =>
    array (
      0 => '全身血管炎损伤冠脉，形成动脉瘤/血栓；心肌炎也可导致 ST-T 改变。',
      1 => '房室结位于 Koch 三角内，靠近三尖瓣隔瓣、冠状窦口与 Todaro 腱。房室结传导速度慢，形成 PR 段的大部分，使心房收缩能够先于心室。',
      2 => '窦房结位于上腔静脉与右心房交界处的界沟附近，是正常心脏的最高起搏点。冲动沿心房肌和结间束向房室结传播，同时激动右房与左房，形成体表 P 波。',
      3 => '窦房结并非一个“点”，而是有起搏细胞与过渡细胞的复合结构；其血供多来自右冠状动脉或左回旋支，缺血可导致窦性心动过缓或停搏。',
    ),
    'answerIndex' => 0,
    'explanation' => '《川崎病心电图》教学要点：全身血管炎损伤冠脉，形成动脉瘤/血栓；心肌炎也可导致 ST-T 改变。',
    'difficulty' => 2,
  ),
