      2 => '房室结位于 Koch 三角内，靠近三尖瓣隔瓣、冠状窦口与 Todaro 腱。房室结传导速度慢，形成 PR 段的大部分，使心房收缩能够先于心室。',
      3 => '离子通道突变导致复极异常；儿童期即可发生 TdP/室颤。',
