  1707 =>
  array (
    'id' => 'sec-advanced-015',
    'chapter' => 'advanced',
    'sourceId' => 'ecg-imaging',
    'stem' => '按本站《心电成像与高级标测》课程，以下哪项描述正确？',
    'options' =>
    array (
      0 => '体表电位与心脏源的关系可通过逆问题求解；病态心脏与噪声使重建困难。',
      1 => '窦房结并非一个“点”，而是有起搏细胞与过渡细胞的复合结构；其血供多来自右冠状动脉或左回旋支，缺血可导致窦性心动过缓或停搏。',
      2 => '窦房结位于上腔静脉与右心房交界处的界沟附近，是正常心脏的最高起搏点。冲动沿心房肌和结间束向房室结传播，同时激动右房与左房，形成体表 P 波。',
      3 => '房室结位于 Koch 三角内，靠近三尖瓣隔瓣、冠状窦口与 Todaro 腱。房室结传导速度慢，形成 PR 段的大部分，使心房收缩能够先于心室。',
    ),
    'answerIndex' => 0,
    'explanation' => '《心电成像与高级标测》教学要点：体表电位与心脏源的关系可通过逆问题求解；病态心脏与噪声使重建困难。',
    'difficulty' => 3,
  ),
